// Helper function to get language-specific content
export function getPostContent(post, lang) {
  const langData = post[lang] || post.en;
  return {
    ...post,
    title: langData.title,
    excerpt: langData.excerpt,
    content: langData.content
  };
}

// Helper function to get related posts based on tags and category
export function getRelatedPosts(currentPost, lang, limit = 3) {
  const currentTags = new Set(currentPost.tags || []);
  const currentCategory = currentPost.category;

  return posts
    .filter(post => post.slug !== currentPost.slug)
    .map(post => {
      let score = 0;
      // Same category gives points
      if (post.category === currentCategory) score += 3;
      // Matching tags give points
      const postTags = post.tags || [];
      postTags.forEach(tag => {
        if (currentTags.has(tag)) score += 1;
      });
      return { post, score };
    })
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map(({ post }) => getPostContent(post, lang));
}
